}
function portfolioView(){let total=state.assets.reduce((n,a)=>n+a.value,0);return `<div class="section-row" style="margin-top:5px"><div><h2>Family portfolio</h2><p>Capital at work, built one generation at a time.</p></div><span class="move-count">${state.assets.length} HOLDINGS</span></div><section class="card wealth-card"><div class="section-head"><div class="section-title">Productive assets</div><div class="mono">${compact(total)} TOTAL VALUE</div></div>${state.assets.length?`<div class="portfolio-list">${state.assets.map((a,i)=>`<div class="asset-row"><strong>${a.name}<br><span style="font:9px 'DM Sans';color:#88938a">${a.kind} · ${a.risk} risk</span></strong><span>${compact(a.value)}<br>value</span><span>${compact(a.value*a.yield)}<br>annual income</span></div>`).join('')}</div>`:`<div class="empty">Your family’s first enterprise is waiting to be acquired.<br>Choose “Explore deals” on the home screen to begin.</div>`}<div class="asset-row" style="border-bottom:1px solid var(--line);margin-top:4px"><strong>Family trust</strong><span>${compact(state.trust)}<br>protected</span><span>${compact(state.trust*.045)}<br>annual income</span></div></section><section class="card wealth-card" style="margin-top:14px"><div class="section-head"><div class="section-title">Stewardship & people</div><div class="mono">NON-FINANCIAL CAPITAL</div></div><div class="stats"><div class="stat"><label>Reputation</label><b>${state.reputation} / 100</b><small>Community standing</small></div><div class="stat"><label>Education</label><b>${compact(state.education)}</b><small>Next-gen investment</small></div><div class="stat"><label>Philanthropy</label><b>${compact(state.philanthropy)}</b><small>Giving to date</small></div></div></section><div class="bottom-grid"><section class="card event-card"><div class="event-icon">✧</div><div><div class="event-tag">A PRINCIPLE TO REMEMBER</div><div class="event-title">Wealth is a responsibility.</div><p class="event-body">Strong family enterprises combine patient capital with good governance, capable people, and a commitment to the communities around them.</p></div></section></div>`}
function ledgerView(){return `<div class="section-row" style="margin-top:5px"><div><h2>Family book</h2><p>A record of decisions, seasons, and the values behind them.</p></div><span class="move-count">${state.logs.length} ENTRIES</span></div><section class="card wealth-card"><div class="section-head"><div class="section-title">Family chronicle</div><div class="mono">${state.year} · ${state.logs.length} YEARS</div></div><div class="portfolio-list">${state.logs.length?state.logs.slice().reverse().map(l=>`<div class="ledger-item"><span class="ledger-year">${l.year}</span><div><strong>${l.title}</strong><div style="color:#7b887e;margin-top:3px">${l.body}</div></div></div>`).join(''):`<div class="empty">The family book is open. Your first annual decision will begin the story.</div>`}</div></section><div class="bottom-grid"><section class="card event-card"><div class="event-icon">✧</div><div><div class="event-tag">THE EVERGREEN PRINCIPLES</div><div class="event-title">Think in generations, not quarters.</div><p class="event-body">Diversify holdings. Preserve reserves. Prepare successors. Let your values guide how capital serves both family and community.</p></div></section></div>`}
function setView(next){view=next;render();window.scrollTo(0,0)}
function chooseMove(id){if(state.ended||state.actions>=1)return;selected=id;
if(id==='deal'){showDeals();return}
const options={trust:{title:'Establish a family trust',amount:250000,ok:s=>{s.trust+=250000;s.reputation=Math.min(100,s.reputation+2);return 'A protected foundation for the next generation.'}},academy:{title:'Invest in family education',amount:60000,ok:s=>{s.education+=60000;s.reputation=Math.min(100,s.reputation+2);return 'Future leaders gain the tools to steward capital.'}},give:{title:'Make a community endowment',amount:40000,ok:s=>{s.philanthropy+=40000;s.reputation=Math.min(100,s.reputation+7);return 'Your family invests in a stronger community.'}},council:{title:'Form a family council',amount:90000,ok:s=>{s.cash-=90000;s.reputation=Math.min(100,s.reputation+9);s.education+=15000;return 'A shared purpose and clear governance strengthen the family.'}},reserve:{title:'Build a protected reserve',amount:150000,ok:s=>{s.trust+=150000;s.reputation=Math.min(100,s.reputation+1);return 'Your reserve is protected and earns a steady 4.5%.'}}};const o=options[id];if(!o||state.cash<o.amount){notify('Not enough liquid capital for this move.');return}confirmModal(o.title,`Commit ${money(o.amount)}? This uses your one strategic move for ${state.year}.`,()=>{state.cash-=o.amount;o.ok(state);state.actions=1;state.logs.push({year:state.year,title:o.title,body:o.ok.toString().includes('')?`Committed ${money(o.amount)} toward family continuity.`:''});save();selected=null;notify('Decision recorded in the family book.');render()});}
function showDeals(){let choices=[...deals].sort(()=>Math.random()-.5).slice(0,3);let html=`<div class="eyebrow">A GENERATIONAL INVESTMENT</div><h2>Explore the deal book</h2><p>Select one enterprise to acquire. Businesses generate annual income and appreciate over time. You can close the deal only if you have enough liquid capital.</p><div class="portfolio-list">${choices.map(d=>`<div class="asset-row" style="grid-template-columns:1fr auto"><div><strong>${d.icon} &nbsp;${d.name}</strong><div style="font:10px 'DM Sans';color:#7c887f;margin-top:4px">${d.desc}</div><span>${d.kind} · ${d.risk} risk · ${(d.yield*100).toFixed(1)}% yield</span></div><button class="confirm" style="border:0;border-radius:3px;padding:10px;background:${state.cash>=d.cost?'#204e3a':'#a9b0a7'};color:white;font:10px 'DM Mono';white-space:nowrap" onclick="buyDeal('${d.id}')">${money(d.cost)}</button></div>`).join('')}</div><div class="modal-actions"><button onclick="closeModal()">BACK</button></div>`;openModal(html)}
function buyDeal(id){let d=deals.find(x=>x.id===id);if(!d||state.cash<d.cost){notify('Not enough liquid capital for this enterprise.');return}state.cash-=d.cost;state.assets.push({id:d.id,name:d.name,kind:d.kind,value:d.cost,yield:d.yield,growth:d.growth,risk:d.risk});state.actions=1;state.logs.push({year:state.year,title:`Acquired ${d.name}`,body:`Invested ${money(d.cost)} in ${d.kind.toLowerCase()} with a ${(d.yield*100).toFixed(1)}% annual yield.`});save();closeModal();selected=null;render();notify(`${d.name} joins your family portfolio.`)}
function confirmModal(title,body,action){openModal(`<div class="eyebrow">FAMILY OFFICE DECISION</div><h2>${title}</h2><p>${body}</p><div class="modal-actions"><button onclick="closeModal()">RECONSIDER</button><button class="confirm" id="modalConfirm">CONFIRM MOVE</button></div>`);document.getElementById('modalConfirm').onclick=()=>{closeModal();action()}}
function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBack').classList.add('show')}
function closeModal(){document.getElementById('modalBack').classList.remove('show')}
document.getElementById('modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()});
function advanceYear(){if(state.ended){resetGame();return}if(state.actions<1){notify('Choose one strategic move before closing the year.');return}let before=wealth();let earned=income();state.cash+=earned;state.cash-=65000;state.assets.forEach(a=>a.value*=1+a.growth);state.trust*=1.045;let event=events[(Math.floor((state.year-2026)/2)+1)%events.length];let effect=event.effect(state);state.history.push({year:state.year,wealth:before});let result=`Annual income ${money(earned)}; operating costs $65,000. ${effect}.`;state.logs.push({year:state.year,title:event.title,body:result});state.year++;state.actions=0;selected=null;if(state.year>=2046||legacyScore()>=100)state.ended=true;save();render();window.scrollTo(0,0);notify(`${event.title} · ${effect}`)}
function confirmReset(){confirmModal('Begin a new legacy?',`This will replace your current family record and return to 2026 with ${money(START.cash)} in starting capital.`,resetGame)}
function resetGame(){state=structuredClone(START);view='home';selected=null;save();closeModal();render();window.scrollTo(0,0);notify('A new family story begins.')}
function notify(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
render();
</script>
</body>
</html>

